  // ── Sayfa Bütünlüğü (9. tür) ──
  'page.iv1m': '1 dk', 'page.iv5m': '5 dk', 'page.iv10m': '10 dk', 'page.iv15m': '15 dk',
  'page.iv30m': '30 dk', 'page.iv1h': '1 sa', 'page.iv12h': '12 sa', 'page.iv24h': '24 sa',
  'page.title':          'Sayfa Bütünlüğü İzleme',
  'page.subtitle':       'İzlenen sayfanın kod seviyesinde sağlıklı yüklendiğini doğrular: kırık link/kaynak, mixed content ve içerik anomalileri.',
  'page.howTitle': 'Bu izleme nasıl ve nereden yapılıyor?',
  'page.how1': 'HTML indirme + ayrıştırma: sayfanın HTML\'i indirilir (kurumsal proxy üzerinden, 443) ve jsoup ile kaynak envanteri çıkarılır — img (src/srcset), CSS (link[stylesheet]), JS (script[src]), site içi/dışı linkler (a[href]), iframe, favicon ve preload font\'lar. Göreli adresler sayfanın URL\'ine göre mutlak hale getirilir; tekilleştirilir.',
  'page.how2': 'Kaynak doğrulama: her kaynak sınırlı eşzamanlılıkla (nezaket + tek-pod yük koruması) kontrol edilir — önce HEAD, sunucu desteklemiyorsa (405/501) GET\'e düşülür. 404/410 ve 5xx = KIRIK, süre eşiğini aşan = YAVAŞ, yanıt hiç gelmezse (bağlantı zaman aşımı) = ZAMAN AŞIMI. Kaynak başına tek istek, tanımlayıcı User-Agent (SiteMonitor-PageCheck).',
  'page.how2b': 'Zaman aşımı: izleme sunucusunun ağ noktasından erişilemeyen kaynaklar (özellikle üçüncü-taraf CDN/analytics) tarayıcıda sorunsuz yüklenebilir. Zaman aşımının KENDİ sayacı vardır — KIRIK sayacına hiçbir zaman karışmaz (kesin kırık URL ile yanıt vermeyen URL ayrı raporlanır). Monitör başına "Zaman aşımlarını izle" anahtarı (varsayılan açık) yalnız durumu/alarmı etkiler: kapalıysa zaman aşımları kartı sorunlu göstermez ve alarm üretmez; sayaçta ve sorun tablosunda yine görünürler.',
  'page.how3': 'Mixed content: HTTPS bir sayfada http:// ile yüklenen kaynak "mixed content" olarak işaretlenir — tarayıcı bunları engelleyebilir/uyarır. Mixed content için monitör başına ayrı bir "alarm üretsin" anahtarı vardır (varsayılan açık); kapatılırsa mixed content yine tespit edilip tabloda gösterilir ama alarm üretmez.',
  'page.how4': 'Birinci / üçüncü taraf ayrımı: kaynağın host\'u sayfayla aynı origin (aynı alan/alt-alan) ise birinci-taraf, dış origin ise üçüncü-taraf (·3P rozeti). Varsayılan olarak yalnız birinci-taraf kırıkları e-posta alarmı üretir (üçüncü-taraf reklam/analytics kaynakları sık kırılır ve site sahibinin kontrolünde değildir); monitör başına "üçüncü-tarafı da dahil et" açılabilir.',
  'page.how5': 'İki mod: Tek Sayfa yalnız hedef URL\'i sık (dakikalar) kontrol eder. Site Tarama, same-origin linkleri tanımlı derinlik + azami sayfa limiti dahilinde SEYREK (günlük) tarar — robots.txt Disallow kurallarına uyar, varsa sitemap.xml\'i tohum alır, aynı anda tek site taranır. "Hariç tutulan desenler" ile bilinçli 404\'ler / dış izleme pikselleri elenir.',
  'page.how6': 'Durum & alarm: OK (temiz) → DEGRADED (sayfa açılıyor ama kırık/mixed kaynak var) → DOWN (ana sayfa hiç alınamıyor). Alarm ancak N ardışık kontrolde SÜREN bir sorunla tetiklenir (tek seferlik takılmalar yanlış-pozitif üretmez) ve sorun giderilince otomatik kapanır. DOWN → KRİTİK, DEGRADED → YÜKSEK. Yanlış-pozitif önleme: belirsiz durumlar (403/429/503 gibi WAF/rate-limit — tabloda "Belirsiz") alarm ÜRETMEZ. Dış linkler (a[href]) yalnız KESİN ölümde alarm sayılır: 404/410 veya hedefin hiç çözülememesi/bağlantı kurulamaması (DNS kaydı silinmiş site gibi); 5xx/zaman aşımı/belirsiz dış link alarm üretmez, yalnız tabloda görünür.',
  'page.how7': 'Güvenlik & saklama: istek atılan HER URL — ana sayfa, ayrıştırmadan çıkan her kaynak ve her yönlendirme (redirect) adımı — SSRF denetiminden geçer; iç ağ / bulut-metadata adreslerine işaret eden kaynaklar engellenir (parse\'tan gelen URL\'ler kullanıcı girdisi kadar güvensiz sayılır). İçerik hash\'i + gövde boyutu sapması defacement sinyali olarak (şimdilik bilgi amaçlı) kaydedilir. Yalnız SORUNLU kaynaklar saklanır; geçmiş yapılandırılabilir süreyle tutulup gece otomatik temizlenir.',
  'page.how8': 'KIRIK görünce aksiyon: "Kırık" = sayfa açılıyor ama içindeki o parça yüklenemiyor (erişim kesintisi DEĞİL). HTTP koduna bak — 404/410: dosya yok/taşınmış → sayfadaki referansı güncelle/kaldır ya da dosyayı geri koy (deploy sonrası isim değiştiyse cache temizlet); 5xx: kaynağın sunucusu/CDN\'i hatalı → o servisin sahibine ilet; Zaman aşımı/bağlantı yok → ağ-firewall erişimini ve kaynak sunucusunu kontrol ettir. Öncelik: kırık CSS/JS sayfayı bozar (yüksek), kırık görsel kozmetiktir, kırık iç link kullanıcıyı 404\'e götürür. Sorun giderilince alarm kendiliğinden kapanır.',
