  'dom.title':       'Domain Expiry Monitoring',
  'dom.subtitle':    'Monitor domain registration (registrar) expiry via RDAP/WHOIS; expiry, registrar, EPP status codes and nameservers.',
  'dom.autoRefresh': 'Auto refresh: {0}s',
