  'dom.dashTotal': 'Total', 'dom.dashOk': 'OK', 'dom.dashWarning': 'Warning', 'dom.dashCritical': 'Critical', 'dom.dashUnknown': 'Unknown', 'dom.dashChanged': 'Changed',
