  'dom.daysLeft': 'Days left', 'dom.expiry': 'Expiry', 'dom.registrar': 'Registrar', 'dom.source': 'Source', 'dom.sourceVia': 'whois source that answered', 'dom.nsResolves': 'NS resolves', 'dom.lastCheck': 'Last check',
