  'http.confirmHint': 'On detection, the condition is re-verified this many times at this interval before alarming (default 3 × 30s; 0 = alarm immediately). Recovery: the alarm auto-resolves only after this many consecutive successful checks (default 3).',
  'http.testError': 'Test error', 'http.testMet': 'Condition met', 'http.testNotMet': 'Condition not met',
